/*
 * A232644  Sequence (or tree) generated by these rules: 1 is in S, and if x
 *          is in S, then x + 1 and 2*x + 3 are in S, and duplicates are
 *          deleted as they occur.
 * https://oeis.org/A232644
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is generated by a breadth‑first tree. 1 is in the set S,
 *            and if x∈S then x+1 and 2*x+3 are in S. The sequence consists of
 *            the values in the order of their first appearance
 * Range:     u8 n <= 97, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

/* dynamic generation of the tree; results are stored
   in a static array growing as needed */

static seq_t *seq = NULL;        /* array of produced terms */
static size_t seq_cap = 0;       /* allocated capacity of seq */
static size_t seq_len = 0;       /* number of terms stored */

/* enlarge seq so that it can hold at least 'need' elements */
static void ensure_seq_cap(size_t need)
{
    if (need <= seq_cap) return;
    size_t ncap = seq_cap ? seq_cap << 1 : 8;
    while (ncap < need) ncap <<= 1;
    seq = (seq_t *)realloc(seq, ncap * sizeof(seq_t));
    if (!seq) abort(); /* out of memory */
    seq_cap = ncap;
}

/* linear search: return true if 'v' is already in seq[0..seq_len) */
static bool already_seen(seq_t v)
{
    for (size_t i = 0; i < seq_len; ++i)
        if (seq[i] == v) return true;
    return false;
}

/* --------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;          /* safety for offset 1 */

    /* initialise the sequence on first call */
    if (!seq) {
        ensure_seq_cap(8);
        seq[0] = (seq_t)1;
        seq_len = 1;
    }

    /* breadth‑first expansion until we have n terms */
    static size_t parent = 0;              /* next node to process */

    while (seq_len < (size_t)n) {
        seq_t x = seq[parent++];
        seq_t c1 = x + (seq_t)1;
        if (!already_seen(c1)) {
            ensure_seq_cap(seq_len + 1);
            seq[seq_len++] = c1;
        }
        seq_t c2 = (x * (seq_t)2) + (seq_t)3;
        if (!already_seen(c2)) {
            ensure_seq_cap(seq_len + 1);
            seq[seq_len++] = c2;
        }
    }

    return seq[n - 1];
}
